mapper.select:
SELECT

FROM ccds_water_source w
WHERE w.station_id = #{stationId}
  AND w.name = #{name}
  AND w.deleted_at IS NULL
LIMIT 1

mapper.update:
UPDATE ccds_water_source
SET deleted_at = #{deletedAt},
    name = CONCAT(LEFT(name, 59 - CHAR_LENGTH(id)), '#DEL#', id),
    gmt_modified = #{gmtModified}
WHERE id = #{id}
  AND deleted_at IS NULL
